test.describe('FR-014: failed add and failed load — run group parallel', () => {
  // read-only: the failing request is made to fail on this page only and nothing is created

  test('[TC-TODO-022] When the service cannot be reached, adding shows "The task was not added. Try again." and no task appears', { tag: ['@negative', '@run:parallel'] }, async ({ page, qaRun }, testInfo) => {
    const notAdded = `${qaRun}-Not added`;
    let taskList = await step('Open the To-Do List application [E1] — the text "Loading tasks…" appears', () => TaskListPage.open(page));
    await step('Wait until "Loading tasks…" clears — no task titled "QA-<run>-Not added" is listed', async () => {
      await taskList.waitForListReady();
      await taskList.expectNoTaskTitled(notAdded);
    });
    await step('Type "QA-<run>-Not added" [D2] in "New task" — the field shows it', () => taskList.typeTitle(notAdded));
    await step('Make the To-Do List service unreachable for the next request — the field still shows the title', async () => {
      taskList.makeServiceUnreachableForNextChange();
      await taskList.expectFieldValue(notAdded);
    });
    await step('Click "Add" — "The task was not added. Try again." is shown near the list', async () => {
      await taskList.clickAdd();
      await taskList.expectErrorMessage('The task was not added. Try again.');
    });
    await step('Check the task list — no task titled "QA-<run>-Not added" is listed', () => taskList.expectNoTaskTitled(notAdded));
    taskList = await step('Close the browser window and open [E1] in a new browser window (service reachable) — "Loading tasks…" appears', () => taskList.reopenInNewWindow());
    await step('Wait until "Loading tasks…" clears — the list is shown', () => taskList.waitForListReady());
    await captureEvidence(taskList.page, testInfo);
    await step('Check after reopening — no task titled "QA-<run>-Not added" is listed', () => taskList.expectNoTaskTitled(notAdded));
  });

  test('[TC-TODO-025] When the list cannot be loaded, "The tasks could not be loaded. Try again." is shown and "Try again" loads it', { tag: ['@negative', '@run:parallel'] }, async ({ page }, testInfo) => {
    const taskList = await step('Open the To-Do List application [E1] with the list unreachable — the text "Loading tasks…" appears', () => TaskListPage.open(page, { listUnreachable: true }));
    await step('Wait until "Loading tasks…" clears — the load error and "Try again" are shown, no task list', () => taskList.waitForLoadFailure());
    await step('Make the To-Do List service reachable again — the load error is still shown', () => taskList.makeListReachableAgain());
    await step('Click "Try again" — the text "Loading tasks…" appears', () => taskList.clickTryAgain());
    await step('Wait until "Loading tasks…" clears — the task list (or "No tasks yet.") is shown', () => taskList.waitForListReady());
    await captureEvidence(taskList.page, testInfo);
    await step('Check the page — the load error and "Try again" are gone', () => taskList.expectLoadErrorGone());
  });
});

test.describe('FR-014, edge case "task already deleted": failed changes — run group serial:task-list', () => {
  // serial:task-list — the cases change or delete tasks of the GLOBAL list (--workers 1); each owns its tasks
  // through its run prefix; mode 'default' keeps them independent
  test.describe.configure({ mode: 'default' });

  test('[TC-TODO-023] When the service cannot be reached, completing shows "The task was not marked as completed. Try again." and the task stays not completed', { tag: ['@negative', '@run:serial-task-list'] }, async ({ page, context, qaRun }, testInfo) => {
    const buyMilk = `${qaRun}-Buy milk`;
    await step('Setup [D2]: add "QA-<run>-Buy milk" through "New task"', () => TaskListPage.addThroughPage(context, [buyMilk]));
    let taskList = await step('Open the To-Do List application [E1] — the text "Loading tasks…" appears', () => TaskListPage.open(page));
    await step('Wait until "Loading tasks…" clears — "QA-<run>-Buy milk" is listed with "Mark as completed"', async () => {
      await taskList.waitForListReady();
      await taskList.task(buyMilk).expectNotCompleted();
    });
    await step('Make the To-Do List service unreachable for the next request — the task is still not completed', async () => {
      taskList.makeServiceUnreachableForNextChange();
      await taskList.task(buyMilk).expectNotCompleted();
    });
    await step('Click "Mark as completed" — "The task was not marked as completed. Try again." is shown', async () => {
      await taskList.task(buyMilk).markCompleted();
      await taskList.expectErrorMessage('The task was not marked as completed. Try again.');
    });
    await step('Check the task — "Mark as completed", no "Completed", title not struck through', () => taskList.task(buyMilk).expectNotCompleted());
    taskList = await step('Close the browser window and open [E1] in a new browser window (service reachable) — "Loading tasks…" appears', () => taskList.reopenInNewWindow());
    await step('Wait until "Loading tasks…" clears — "QA-<run>-Buy milk" is listed', async () => {
      await taskList.waitForListReady();
      await taskList.expectTaskListed(buyMilk);
    });
    await captureEvidence(taskList.page, testInfo);
    await step('Check after reopening — "Mark as completed" and not "Completed"', () => taskList.task(buyMilk).expectNotCompleted());
  });

  test('[TC-TODO-024] When the service cannot be reached, deleting shows "The task was not deleted. Try again." and the task stays', { tag: ['@negative', '@run:serial-task-list'] }, async ({ page, context, qaRun }, testInfo) => {
    const buyMilk = `${qaRun}-Buy milk`;
    await step('Setup [D2]: add "QA-<run>-Buy milk" through "New task"', () => TaskListPage.addThroughPage(context, [buyMilk]));
    let taskList = await step('Open the To-Do List application [E1] — the text "Loading tasks…" appears', () => TaskListPage.open(page));
    await step('Wait until "Loading tasks…" clears — "QA-<run>-Buy milk" is listed', async () => {
      await taskList.waitForListReady();
      await taskList.expectTaskListed(buyMilk);
    });
    await step('Make the To-Do List service unreachable for the next request — the task is still listed', async () => {
      taskList.makeServiceUnreachableForNextChange();
      await taskList.expectTaskListed(buyMilk);
    });
    await step('Click "Delete" — "The task was not deleted. Try again." is shown near the list', async () => {
      await taskList.task(buyMilk).delete();
      await taskList.expectErrorMessage('The task was not deleted. Try again.');
    });
    await step('Check the task list — "QA-<run>-Buy milk" is still listed', () => taskList.expectTaskListed(buyMilk));
    taskList = await step('Close the browser window and open [E1] in a new browser window (service reachable) — "Loading tasks…" appears', () => taskList.reopenInNewWindow());
    await step('Wait until "Loading tasks…" clears — the list is shown', () => taskList.waitForListReady());
    await captureEvidence(taskList.page, testInfo);
    await step('Check after reopening — "QA-<run>-Buy milk" is still listed', () => taskList.expectTaskListed(buyMilk));
  });

  test('[TC-TODO-026] Completing a task someone else deleted shows "This task no longer exists." and removes it', { tag: ['@negative', '@run:serial-task-list'] }, async ({ page, context, qaRun }, testInfo) => {
    const buyMilk = `${qaRun}-Buy milk`;
    await step('Setup [D2]: add "QA-<run>-Buy milk" through "New task"', () => TaskListPage.addThroughPage(context, [buyMilk]));
    const first = await step('Open [E1] in the first browser window — the text "Loading tasks…" appears', () => TaskListPage.open(page));
    await step('Wait until "Loading tasks…" clears — "QA-<run>-Buy milk" is listed with "Mark as completed"', async () => {
      await first.waitForListReady();
      await first.task(buyMilk).expectNotCompleted();
    });
    const second = await step('Open [E1] in a second browser window — the text "Loading tasks…" appears', () => TaskListPage.openSecondWindow(context));
    await step('Wait until "Loading tasks…" clears in the second window — "QA-<run>-Buy milk" is listed', async () => {
      await second.waitForListReady();
      await second.expectTaskListed(buyMilk);
    });
    await step('In the second window, click "Delete" of "QA-<run>-Buy milk" — it disappears there', async () => {
      await second.task(buyMilk).delete();
      await second.expectNoTaskTitled(buyMilk);
    });
    await step('Switch to the first window without reloading — "QA-<run>-Buy milk" is still listed there', async () => {
      await first.page.bringToFront();
      await first.expectTaskListed(buyMilk);
    });
    await step('Click "Mark as completed" of "QA-<run>-Buy milk" — "This task no longer exists." is shown', async () => {
      await first.task(buyMilk).markCompleted();
      await first.expectErrorMessage('This task no longer exists.');
    });
    await captureEvidence(first.page, testInfo);
    await step('Check the task list in the first window — no task titled "QA-<run>-Buy milk"', () => first.expectNoTaskTitled(buyMilk));
  });

  test('[TC-TODO-027] Deleting a task someone else deleted shows "This task no longer exists." and removes it', { tag: ['@negative', '@run:serial-task-list'] }, async ({ page, context, qaRun }, testInfo) => {
    const buyMilk = `${qaRun}-Buy milk`;
    await step('Setup [D2]: add "QA-<run>-Buy milk" through "New task"', () => TaskListPage.addThroughPage(context, [buyMilk]));
    const first = await step('Open [E1] in the first browser window — the text "Loading tasks…" appears', () => TaskListPage.open(page));
    await step('Wait until "Loading tasks…" clears — "QA-<run>-Buy milk" is listed', async () => {
      await first.waitForListReady();
      await first.expectTaskListed(buyMilk);
    });
    const second = await step('Open [E1] in a second browser window — the text "Loading tasks…" appears', () => TaskListPage.openSecondWindow(context));
    await step('Wait until "Loading tasks…" clears in the second window — "QA-<run>-Buy milk" is listed', async () => {
      await second.waitForListReady();
      await second.expectTaskListed(buyMilk);
    });
    await step('In the second window, click "Delete" of "QA-<run>-Buy milk" — it disappears there', async () => {
      await second.task(buyMilk).delete();
      await second.expectNoTaskTitled(buyMilk);
    });
    await step('Switch to the first window without reloading — "QA-<run>-Buy milk" is still listed there', async () => {
      await first.page.bringToFront();
      await first.expectTaskListed(buyMilk);
    });
    await step('Click "Delete" of "QA-<run>-Buy milk" — "This task no longer exists." is shown', async () => {
      await first.task(buyMilk).delete();
      await first.expectErrorMessage('This task no longer exists.');
    });
    await captureEvidence(first.page, testInfo);
    await step('Check the task list in the first window — no task titled "QA-<run>-Buy milk"', () => first.expectNoTaskTitled(buyMilk));
  });
});

test.describe('FR-013, FR-016, SC-003, SC-005: keyboard and timing — run group serial:task-list', () => {
  // serial:task-list — the cases add and delete tasks of the GLOBAL list and depend on positions in it (--workers 1)
  test.describe.configure({ mode: 'default' });

  test('[TC-TODO-028] Adding, completing and deleting a task works with the keyboard only', { tag: ['@positive', '@run:serial-task-list'] }, async ({ page, qaRun }, testInfo) => {
    const keyboard1 = `${qaRun}-Keyboard 1`;
    const keyboard2 = `${qaRun}-Keyboard 2`;
    const taskList = await step('Open the To-Do List application [E1] — the text "Loading tasks…" appears', () => TaskListPage.open(page));
    await step('Wait until "Loading tasks…" clears — the task list (or "No tasks yet.") is shown', () => taskList.waitForListReady());
    await step('Press Tab until "New task" has focus — the focus indicator is visible on it', async () => {
      await taskList.tabToNewTaskField();
      await taskList.expectVisibleFocus(taskList.newTaskInput);
    });
    await step('Type "QA-<run>-Keyboard 1" [D2] — the field shows it', async () => {
      await taskList.typeWithKeyboard(keyboard1);
      await taskList.expectFieldValue(keyboard1);
    });
    await step('Press Enter — "QA-<run>-Keyboard 1" appears as the first task', async () => {
      await taskList.pressEnter();
      await taskList.expectFirstTask(keyboard1);
    });
    await step('Check the "New task" field — it is empty and still has focus', async () => {
      await taskList.expectFieldEmpty();
      await taskList.expectVisibleFocus(taskList.newTaskInput);
    });
    await step('Type "QA-<run>-Keyboard 2" [D2] — the field shows it', async () => {
      await taskList.typeWithKeyboard(keyboard2);
      await taskList.expectFieldValue(keyboard2);
    });
    await step('Press Enter — "QA-<run>-Keyboard 2" appears as the first task, above "QA-<run>-Keyboard 1"', async () => {
      await taskList.pressEnter();
      await taskList.expectCaseOrder(qaRun, [keyboard2, keyboard1]);
    });
    await step('Press Tab until "Mark as completed: QA-<run>-Keyboard 2" has focus — the focus indicator is visible', async () => {
      await taskList.tabUntilFocused(taskList.task(keyboard2).completeButton);
      await taskList.expectVisibleFocus(taskList.task(keyboard2).completeButton);
    });
    await step('Press Enter — "QA-<run>-Keyboard 2" shows the text "Completed"', async () => {
      await taskList.pressEnter();
      await taskList.task(keyboard2).expectCompleted();
    });
    await step('Press Tab or Shift+Tab until "Delete: QA-<run>-Keyboard 2" has focus — the focus indicator is visible', async () => {
      await taskList.tabUntilFocused(taskList.task(keyboard2).deleteButton);
      await taskList.expectVisibleFocus(taskList.task(keyboard2).deleteButton);
    });
    await step('Press Enter — "QA-<run>-Keyboard 2" disappears from the list', async () => {
      await taskList.pressEnter();
      await taskList.expectNoTaskTitled(keyboard2);
    });
    await step('Check the focus — it is on "Delete: QA-<run>-Keyboard 1"', () => taskList.expectVisibleFocus(taskList.task(keyboard1).deleteButton));
    await step('Press Enter — "QA-<run>-Keyboard 1" disappears from the list', async () => {
      await taskList.pressEnter();
      await taskList.expectNoTaskTitled(keyboard1);
    });
    await captureEvidence(taskList.page, testInfo);
    await step('Check the task list — none of the tasks of this case is listed', () => taskList.expectCaseOrder(qaRun, []));
  });

  test('[TC-TODO-031] After add, complete and delete, the list shows the result within 1 second', { tag: ['@positive', '@run:serial-task-list'] }, async ({ page, qaRun }, testInfo) => {
    const timing = `${qaRun}-Timing`;
    const taskList = await step('Open the To-Do List application [E1] — the text "Loading tasks…" appears', () => TaskListPage.open(page));
    await step('Wait until "Loading tasks…" clears — the task list (or "No tasks yet.") is shown', () => taskList.waitForListReady());
    await step('Type "QA-<run>-Timing" [D2] in "New task" — the field shows it', () => taskList.typeTitle(timing));
    await step('Click "Add" — "QA-<run>-Timing" appears as the first task within 1 second', async () => {
      await taskList.clickAdd();
      await taskList.expectFirstTask(timing, { within: RESULT_WITHIN_MS });
    });
    await step('Click "Mark as completed" — the task shows "Completed" within 1 second', async () => {
      await taskList.task(timing).markCompleted();
      await taskList.expectTaskCompletedWithin(timing, RESULT_WITHIN_MS);
    });
    await step('Click "Delete" of "QA-<run>-Timing" — it disappears within 1 second', async () => {
      await taskList.task(timing).delete();
      await taskList.expectNoTaskTitled(timing, { within: RESULT_WITHIN_MS });
    });
    await captureEvidence(taskList.page, testInfo);
    await step('Check the task list — none of the tasks of this case is listed', () => taskList.expectCaseOrder(qaRun, []));
  });
});

test.describe('FR-016, SC-005: automated accessibility scan (WCAG 2.2 AA) — run group serial:empty-list', () => {
  // serial:empty-list — [D1] empties the GLOBAL list first, so this case runs alone (--workers 1)
  test.describe.configure({ mode: 'default' });

  test('[TC-TODO-029] The page has no critical or serious accessibility violations when empty, filled and showing an error', { tag: ['@positive', '@run:serial-empty-list'] }, async ({ page, qaRun, emptyTaskList }, testInfo) => {
    void emptyTaskList;
    const access1 = `${qaRun}-Access 1`;
    const access2 = `${qaRun}-Access 2`;
    const taskList = await step('Open the To-Do List application [E1] — the text "Loading tasks…" appears', () => TaskListPage.open(page));
    await step('Wait until "Loading tasks…" clears — "No tasks yet." is shown and no task is listed', async () => {
      await taskList.waitForListReady();
      await taskList.expectEmptyList();
    });
    await step('Run the accessibility scan on the empty page — 0 critical and 0 serious violations', () => taskList.expectNoSeriousAccessibilityViolations());
    await step('Type "QA-<run>-Access 1" [D2] in "New task" — the field shows it', () => taskList.typeTitle(access1));
    await step('Click "Add" — "QA-<run>-Access 1" is listed as the first task', async () => {
      await taskList.clickAdd();
      await taskList.expectFirstTask(access1);
    });
    await step('Type "QA-<run>-Access 2" [D2] in "New task" — the field shows it', () => taskList.typeTitle(access2));
    await step('Click "Add" — "QA-<run>-Access 2" is listed first, above "QA-<run>-Access 1"', async () => {
      await taskList.clickAdd();
      await taskList.expectCaseOrder(qaRun, [access2, access1]);
    });
    await step('Click "Mark as completed" of "QA-<run>-Access 1" — it shows the text "Completed"', async () => {
      await taskList.task(access1).markCompleted();
      await taskList.task(access1).expectCompleted();
    });
    await step('Run the accessibility scan on the filled list — 0 critical and 0 serious violations', () => taskList.expectNoSeriousAccessibilityViolations());
    await step('Click "Add" with the field empty — "Enter a title for the task." is shown below the field', async () => {
      await taskList.clickAdd();
      await taskList.expectTitleRequiredMessage();
    });
    await step('Run the accessibility scan with the field message — 0 critical and 0 serious violations', () => taskList.expectNoSeriousAccessibilityViolations());
    await step('Make the To-Do List service unreachable for the next request — the two tasks are still listed', async () => {
      taskList.makeServiceUnreachableForNextChange();
      await taskList.expectCaseOrder(qaRun, [access2, access1]);
    });
    await step('Click "Delete" of "QA-<run>-Access 2" — "The task was not deleted. Try again." is shown', async () => {
      await taskList.task(access2).delete();
      await taskList.expectErrorMessage('The task was not deleted. Try again.');
    });
    await captureEvidence(taskList.page, testInfo);
    await step('Run the accessibility scan with the error message — 0 critical and 0 serious violations', () => taskList.expectNoSeriousAccessibilityViolations());
  });
});
